#define GSGL_DEBUG(x)

typedef struct _item {
	int i;
	int j;
	int kerning;
} item;

gsgllist * item_append (gsgllist *list, int i, int j, int kerning)
{
	item *item1;
	
	item1 = (item *) gsgl_malloc(sizeof(item));
	item1->i = i;
	item1->j = j;
	item1->kerning = kerning;

	return gsgl_list_append(list, item1);
}

static int hashfunc (int i, int j)
{
	return (i * j) % TABLE_SIZE;
}

int type1_kerning (int fnt, int i, int j, gsglPage *p)
{
	int h;
	item *itemp;
	gsgllist *list;

	if (fnt < 32 || fnt > 43) return 0;

	h = hashfunc (i,j);
	list = p->library->Table[fnt-32][h];
	if (list == NULL) {
		GSGL_DEBUG(fprintf (stderr, "%d %d %d\n", i, j, 0));
		return 0;
	} else {
		while (list != NULL) {
			itemp = (item *) list->data;
			if (!itemp) return 0;
			if (itemp->i == i && itemp->j == j) {
				GSGL_DEBUG(fprintf (stderr, "%d %d %d\n", i, j, itemp->kerning));
				return itemp->kerning;
			} else {
				list = list->next;
				GSGL_DEBUG(fprintf (stderr, "next\n"));
			}
		}
	}
	GSGL_DEBUG(fprintf (stderr, "%d %d %d\n", i, j, 0));
	return 0;
}

